with deduped as (select * from device_readings qualify row_number() over (partition by device_code order by humidity nulls last, id) = 1) select device_code, case when temp_c >= 33.7 then 'HIGH' else 'LOW' end as temp_c_tier, case when humidity >= 75 then 'HIGH' else 'LOW' end as humidity_tier, size(collect_set(device_code)) as num_device_codes, round(avg(pressure), 2) as avg_pressure, grouping_id() as gid from deduped group by grouping sets ((device_code, case when temp_c >= 33.7 then 'HIGH' else 'LOW' end, case when humidity >= 75 then 'HIGH' else 'LOW' end), (device_code, case when temp_c >= 33.7 then 'HIGH' else 'LOW' end), (device_code))
